USE TestDB;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

BEGIN TRY
    DECLARE @userId INT;
    SET @userId = {{ $json.body.userId || 'NULL' }};

    MERGE dbo.chat_sessions AS target
    USING (SELECT 
        N'{{ $json.body.sessionId }}' AS session_id,
        N'{{ ($json.body.content || "Percakapan Baru").substring(0, 100).replace(/'/g, "''") }}' AS title,
        N'{{ $json.body.database || "TestDB" }}' AS database_name,
        @userId AS user_id
    ) AS source
    ON target.session_id = source.session_id
    WHEN MATCHED THEN
        UPDATE SET 
            updated_at = GETDATE(),
            message_count = message_count + 1,
            user_id = ISNULL(target.user_id, source.user_id)
    WHEN NOT MATCHED THEN
        INSERT (session_id, title, database_name, user_id, message_count)
        VALUES (source.session_id, source.title, source.database_name, source.user_id, 1);

    DECLARE @new_message_id INT;

    INSERT INTO dbo.chat_messages 
        (session_id, message_type, content, status_type, sql_query, metadata, data, user_id, created_at)
    VALUES (
        N'{{ $json.body.sessionId }}',
        N'{{ $json.body.type }}',
        N'{{ ($json.body.content || "").replace(/'/g, "''") }}',
        N'{{ $json.body.statusType || "" }}',
        N'{{ ($json.body.sql || "").replace(/'/g, "''") }}',
        N'{{ JSON.stringify($json.body.metadata || {}).replace(/'/g, "''") }}',
        N'{{ JSON.stringify($json.body.data || []).replace(/'/g, "''") }}',
        @userId,
        GETDATE()
    );

    SET @new_message_id = SCOPE_IDENTITY();

    COMMIT TRANSACTION;

    SELECT @new_message_id AS message_id;

END TRY
BEGIN CATCH
    ROLLBACK TRANSACTION;
    THROW;
END CATCH;
